#include <vector>
#include <algorithm>
#include <unordered_map>

class Solution {
public:
    std::vector<int> arrayRankTransform(std::vector<int>& arr) {
        std::vector<int> sortedArr = arr;
        std::sort(sortedArr.begin(), sortedArr.end());
        std::unordered_map<int, int> ranks;
        int rank = 1;
        for (int x : sortedArr) {
            if (ranks.find(x) == ranks.end()) {
                ranks[x] = rank++;
            }
        }
        std::vector<int> res(arr.size());
        for (size_t i = 0; i < arr.size(); ++i) {
            res[i] = ranks[arr[i]];
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] arrayRankTransform(int[] arr) {
        int[] sortedArr = arr.clone();
        Arrays.sort(sortedArr);
        Map<Integer, Integer> ranks = new HashMap<>();
        int rank = 1;
        for (int x : sortedArr) {
            if (!ranks.containsKey(x)) {
                ranks.put(x, rank++);
            }
        }
        int[] res = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            res[i] = ranks.get(arr[i]);
        }
        return res;
    }
}

var arrayRankTransform = function(arr) {
    const sortedUniq = Array.from(new Set(arr)).sort((a, b) => a - b);
    const ranks = new Map();
    for (let i = 0; i < sortedUniq.length; i++) {
        ranks.set(sortedUniq[i], i + 1);
    }
    return arr.map(x => ranks.get(x));
};
